namespace sv_e9c28b872dfe42fcbe6caaa1ebf8aab7.Client.Models;

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public sealed record StatusUpdate(
    DateTimeOffset Timestamp,
    string Status,
    string Location);

using sv_e9c28b872dfe42fcbe6caaa1ebf8aab7.Client.Models;

namespace sv_e9c28b872dfe42fcbe6caaa1ebf8aab7.Client.Services;

public interface IShipmentService
{
    Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;
using sv_e9c28b872dfe42fcbe6caaa1ebf8aab7.Client.Models;

namespace sv_e9c28b872dfe42fcbe6caaa1ebf8aab7.Client.Services;

/// <summary>
/// WASM-side implementation that forwards calls to the server API.
/// </summary>
public sealed class HttpShipmentService(HttpClient http) : IShipmentService
{
    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var shipment = await http.GetFromJsonAsync<Shipment>(
            $"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        return shipment ?? throw new InvalidOperationException("Shipment not found.");
    }
}

using sv_e9c28b872dfe42fcbe6caaa1ebf8aab7.Client.Models;
using sv_e9c28b872dfe42fcbe6caaa1ebf8aab7.Client.Services;

namespace sv_e9c28b872dfe42fcbe6caaa1ebf8aab7.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment(
            "PKG-001",
            "In Transit",
            "Chicago, IL",
            DateTimeOffset.UtcNow.AddDays(2),
            [
                new StatusUpdate(DateTimeOffset.UtcNow.AddDays(-3), "Picked Up", "New York, NY"),
                new StatusUpdate(DateTimeOffset.UtcNow.AddDays(-2), "In Transit", "Philadelphia, PA"),
                new StatusUpdate(DateTimeOffset.UtcNow.AddDays(-1), "In Transit", "Chicago, IL"),
            ]),
        ["PKG-002"] = new Shipment(
            "PKG-002",
            "Delivered",
            "San Francisco, CA",
            DateTimeOffset.UtcNow.AddDays(-1),
            [
                new StatusUpdate(DateTimeOffset.UtcNow.AddDays(-5), "Picked Up", "Seattle, WA"),
                new StatusUpdate(DateTimeOffset.UtcNow.AddDays(-3), "In Transit", "Portland, OR"),
                new StatusUpdate(DateTimeOffset.UtcNow.AddDays(-1), "Delivered", "San Francisco, CA"),
            ]),
        ["PKG-003"] = new Shipment(
            "PKG-003",
            "Out for Delivery",
            "Austin, TX",
            DateTimeOffset.UtcNow,
            [
                new StatusUpdate(DateTimeOffset.UtcNow.AddDays(-4), "Picked Up", "Miami, FL"),
                new StatusUpdate(DateTimeOffset.UtcNow.AddDays(-2), "In Transit", "Houston, TX"),
                new StatusUpdate(DateTimeOffset.UtcNow.AddHours(-3), "Out for Delivery", "Austin, TX"),
            ]),
    };

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"No shipment found for tracking number '{trackingNumber}'.");
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_e9c28b872dfe42fcbe6caaa1ebf8aab7.Client.Models
@using sv_e9c28b872dfe42fcbe6caaa1ebf8aab7.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

<h3>Shipment Tracking</h3>

@if (_loading)
{
    <div class="alert alert-info" role="status">
        <span class="spinner-border spinner-border-sm" aria-hidden="true"></span>
        Loading shipment <strong>@TrackingNumber</strong>&hellip;
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm mt-2" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is not null)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">@_shipment.TrackingNumber</h5>
            <p><strong>Status:</strong> @_shipment.Status</p>
            <p><strong>Location:</strong> @_shipment.Location</p>
            <p><strong>Estimated Delivery:</strong> @_shipment.EstimatedDelivery.ToString("f")</p>
        </div>
    </div>

    <h5>Status History</h5>
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Time</th>
                <th>Status</th>
                <th>Location</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var update in _shipment.StatusUpdates)
            {
                <tr>
                    <td>@update.Timestamp.ToString("g")</td>
                    <td>@update.Status</td>
                    <td>@update.Location</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private CancellationTokenSource? _cts;
    private Shipment? _shipment;
    private string? _errorMessage;
    private bool _loading;

    [Parameter]
    public string TrackingNumber { get; set; } = string.Empty;

    protected override Task OnParametersSetAsync() => LoadShipmentAsync();

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request (handles navigation to a new tracking number)
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _shipment = null;
        _errorMessage = null;
        _loading = true;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation away or dispose — silently abandon.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading the shipment. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private Task RetryAsync() => LoadShipmentAsync();

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

